<?php
 namespace Pterodactyl\Jobs\Dezerx; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Cache; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Queue\Middleware\WithoutOverlapping; use Pterodactyl\Services\Dezerx\Minecraft\RegionFile; use Pterodactyl\Services\Dezerx\Minecraft\MapRenderer; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class RenderPlayerMapTile extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 300; public int $tries = 1; private const MAX_BYTES = 64_000_000; public function __construct(public Server $server, public string $path, public string $destination) { $this->queue = 'standard'; } public static function pendingKey(string $destination): string { return 'dezerx:playermap:pending:' . sha1($destination); } public function middleware(): array { return [(new WithoutOverlapping($this->destination))->dontRelease()]; } public function handle(): void { $local = $this->destination . '.mca'; try { if (is_file($this->destination)) { return; } $raw = (new ServerFiles($this->server))->fileContents($this->path, self::MAX_BYTES); if ($raw === null || strlen($raw) < 8192 || file_put_contents($local, $raw) === false) { return; } $chunks = RegionFile::index($local); if ($chunks !== null) { MapRenderer::render($local, $chunks, $this->destination); } } finally { @unlink($local); Cache::forget(self::pendingKey($this->destination)); } } } 